  {
    "message_id": "M01",
    "message": "My export opens correctly but a category visible in the dashboard is absent from the file. Please help me check the report output."
  },
  {
    "message_id": "M02",
    "message": "The source file uploads, but the date column is rejected during import. I want help understanding the required format."
  },
  {
